22	const USAGE = `Usage: trunk-sync seance <file:line> [--inspect]
23	       trunk-sync seance --list
24	
25	Find which Claude or Codex session wrote a line of code and fork that session.
26	
27	Arguments:
28	  <file:line>   File path and line number, e.g. src/main.ts:42
29	
30	Options:
31	  --inspect     Show commit and session info without launching the CLI
32	  --list        List all trunk-sync sessions found in git history
33	  -h, --help    Show this help message`;
