35	function listSessions(): void {
36	  let output: string;
37	  try {
38	    output = execSync('git log --format="%H" --grep="^auto("', {
39	      encoding: "utf-8",
40	    }).trim();
41	  } catch {
42	    output = "";
43	  }
44	
45	  if (!output) {
46	    console.log("No trunk-sync sessions found in git history.");
47	    return;
48	  }
49	
50	  const shas = output.split("\n");
51	  const seen = new Map<string, { sha: string; subject: string; date: string }>();
52	
53	  for (const sha of shas) {
54	    const body = getCommitBody(sha);
55	    const sessionId = extractSessionId(body);
56	    if (sessionId && !seen.has(sessionId)) {
57	      seen.set(sessionId, {
58	        sha,
59	        subject: getCommitSubject(sha),
60	        date: getCommitDate(sha),
61	      });
62	    }
63	  }
64	
65	  if (seen.size === 0) {
66	    console.log("No trunk-sync sessions found in git history.");
67	    return;
68	  }
69	
70	  console.log("SESSION_ID                            SUBJECT                                          DATE");
71	  console.log("─".repeat(100));
72	  for (const [sessionId, { subject, date }] of seen) {
73	    const truncSubject = subject.length > 48 ? subject.slice(0, 45) + "..." : subject;
74	    const shortDate = date.slice(0, 19);
75	    console.log(
76	      `${sessionId.padEnd(38)}${truncSubject.padEnd(50)}${shortDate}`
77	    );
78	  }
79	}
80	
81	/**
82	 * Derive the Claude project slug for a given directory path.
83	 * Claude replaces "/" and "." with "-" in the absolute path.
84	 */
85	function projectSlug(dirPath: string): string {
86	  return dirPath.replace(/[/.]/g, "-");
87	}
88	
89	/**
90	 * Create a truncated copy of a session transcript, containing only messages
91	 * up to the given timestamp. The copy is written into the worktree's project
92	 * directory so Claude can find it via --resume.
93	 */
94	function rewindTranscript(
95	  transcriptPath: string,
96	  commitTimestamp: string,
97	  worktreePath: string
98	): { path: string; id: string } | null {
99	  const expandedPath = transcriptPath.replace(/^~/, process.env.HOME || "~");
100	  if (!existsSync(expandedPath)) return null;
101	
102	  // Git timestamps have second precision; transcript timestamps have millisecond
103	  // precision. Adding 999ms includes the full second of the commit so we don't
104	  // cut off transcript entries that fall within the same second as the commit.
105	  const cutoff = new Date(commitTimestamp).getTime() + 999;
106	  const lines = readFileSync(expandedPath, "utf-8").split("\n").filter(Boolean);
107	
108	  // Find the last line whose timestamp is <= the commit timestamp.
109	  let cutIndex = -1;
110	  for (let i = 0; i < lines.length; i++) {
111	    try {
112	      const obj = JSON.parse(lines[i]);
113	      const ts = obj.timestamp;
114	      if (ts && new Date(ts).getTime() <= cutoff) {
115	        cutIndex = i;
116	      }
117	    } catch {
118	      // Non-JSON lines (shouldn't happen) — include them if before cutoff
119	    }
120	  }
121	
122	  if (cutIndex < 0) return null;
123	
124	  const newId = randomUUID();
125	  // Write into the project directory Claude will use for the worktree.
126	  const home = process.env.HOME || "~";
127	  const projectDir = join(home, ".claude", "projects", projectSlug(worktreePath));
128	  mkdirSync(projectDir, { recursive: true });
129	  const newPath = join(projectDir, `${newId}.jsonl`);
130	  // Rewrite sessionId and cwd so Claude recognises this as a valid session.
131	  const rewritten = lines.slice(0, cutIndex + 1).map((line) => {
132	    try {
133	      const obj = JSON.parse(line);
134	      if (obj.sessionId) obj.sessionId = newId;
135	      if (obj.cwd) obj.cwd = worktreePath;
136	      return JSON.stringify(obj);
137	    } catch {
138	      return line;
139	    }
140	  });
141	  writeFileSync(newPath, rewritten.join("\n") + "\n");
142	
143	  return { path: newPath, id: newId };
144	}
145	
146	function runCodexSeance(args: {
147	  transcriptSource: string;
148	  commitTimestamp: string;
149	  worktreePath: string;
150	  sha: string;
151	  prompt: string;
152	}): void {
153	  const { transcriptSource, commitTimestamp, worktreePath, sha, prompt } = args;
154	  const home = process.env.HOME || "~";
155	  const newId = randomUUID();
156	  const rolloutLines = readFileSync(transcriptSource, "utf-8").split("\n").filter(Boolean);
157	  const rewound = rewindCodexRollout({
158	    rolloutLines,
159	    commitTimestamp,
160	    worktreePath,
161	    newId,
162	    homeDir: home,
163	  });
164	  if (!rewound) {
165	    console.error(`Could not rewind Codex rollout for commit ${shortSha(sha)}.`);
166	    process.exit(1);
167	  }
168	  mkdirSync(join(rewound.targetPath, ".."), { recursive: true });
169	  writeFileSync(rewound.targetPath, rewound.lines.join("\n") + "\n");
170	
171	  console.log(`Rewound session to commit ${shortSha(sha)} (${commitTimestamp})`);
172	  console.log(`Worktree at ${worktreePath}`);
173	
174	  const result = spawnSync(
175	    "codex",
176	    [
177	      "exec",
178	      "--sandbox", "read-only",
179	      "--ask-for-approval", "never",
180	      "--skip-git-repo-check",
181	      "-C", worktreePath,
182	      "resume", newId,
183	      prompt,
184	    ],
185	    { stdio: "inherit" },
186	  );
187	
188	  try { unlinkSync(rewound.targetPath); } catch { /* best-effort */ }
189	  try {
190	    execSync(`git worktree remove "${worktreePath}"`, { stdio: "pipe" });
191	  } catch {
192	    console.error(`Note: worktree left at ${worktreePath} — remove with: git worktree remove "${worktreePath}"`);
193	  }
194	  process.exit(result.status ?? 1);
195	}
196	
197	function inspectOrLaunch(fileRef: string, inspect: boolean): void {
198	  const { file, line } = parseFileRef(fileRef);
199	
200	  const blameResult = blame(file, line);
201	  const sha = blameResult.sha;
202	  const origLine = blameResult.origLine;
203	  if (/^0+$/.test(sha)) {
204	    console.error(`Line ${line} has uncommitted changes.`);
205	    process.exit(1);
206	  }
207	
208	  const body = getCommitBody(sha);
209	  const sessionId = extractSessionId(body);
210	  const subject = getCommitSubject(sha);
211	
212	  if (!sessionId) {
213	    console.error(`Commit ${shortSha(sha)} was not created by trunk-sync.`);
214	    process.exit(1);
215	  }
216	
217	  if (inspect) {
218	    console.log(`Commit:   ${sha}`);
219	    console.log(`Subject:  ${subject}`);
220	    console.log(`Session:  ${sessionId}`);
221	    return;
222	  }
223	
224	  const agent = extractAgent(body);
225	  const cliName = agent === "codex" ? "codex" : "claude";
226	  if (!commandExists(cliName)) {
227	    console.error(`${cliName} CLI not found.`);
228	    process.exit(1);
229	  }
230	
